class Solution:
    def findPeakElement(self, nums: List[int]) -> int:
        lo, hi = 0, len(nums) - 1
        while lo < hi:  # each iteration halves [lo, hi]
            mid = (lo + hi) // 2
            if nums[mid] < nums[mid + 1]:
                lo = mid + 1  # rising slope: a peak exists right of mid
            else:
                hi = mid      # falling slope: mid or something left of it is a peak
        return lo  # the single remaining index is a peak
